// === Tab: mySketch ===
/// changes: cemysf
// - made frag string -> frag function that returns the string
// - inserted initial function values as strings
// - added UI to set function strings and reload shader conder

//Fork basic sjadder structure from https://openprocessing.org/sketch/923286
//p5.js shader basic structure ref from https://www.openprocessing.org/sketch/920144
//Learn tutorial from https://www.youtube.com/watch?v=EO2ax570wKo&list=PL4neAtv21WOmIrTrkNO3xCyrxg4LKkrF7&index=24

let theShader;
let sourceGraphics,shaderGraphics;
var sizeMin;
var boolTrigger;

function preload(){
	theShader = createShader(vert, frag())
}

function setup() {
	sizeMin = min(innerHeight, innerWidth)
	createCanvas(sizeMin,sizeMin);
	sourceGraphics= createGraphics(width,height)
	shaderGraphics = createGraphics(width,height,WEBGL)
	sourceGraphics.background(0) 
}

function draw() {
	sourceGraphics.background(0, 255)

	shaderGraphics.shader(theShader)
	theShader.setUniform('u_resolution',[width/sizeMin,height/sizeMin])
	theShader.setUniform('u_time',millis()*0.001)
	theShader.setUniform('u_tex',sourceGraphics)
	theShader.setUniform('u_mouseX',(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))
	theShader.setUniform('u_mouseY',(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))

	shaderGraphics.rect(-width/2,-height/2,width,height)
	image(sourceGraphics,0,0)
	image(shaderGraphics,0,0)
}

// === Tab: frag ===
//By me
// noprotect

let noise_i = "floor", noise_f="fract";
let f1 = "sin", f2 = "cos";
let f1_1 = "sin", f1_2 = "sin";

const frag = () => `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform float u_mouseX;
	uniform float u_mouseY;
	uniform float u_time;
	uniform sampler2D u_tex;
	varying vec2 var_vertTexCoord;

	float random (in vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(12.9898,78.233)))
                 * 43758.5453123);
	}


	float noise (in vec2 st) {
    vec2 i = ${noise_i}(st);
    vec2 f = ${noise_f}(st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    // Smooth Interpolation

    // Cubic Hermine Curve.  Same as SmoothStep()
    vec2 u = f*f*(3.0-2.0*f);
    // u = smoothstep(0.,1.,f);

    // Mix 4 coorners percentages
    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
	}

	void main(){
		vec2 coord = var_vertTexCoord.xy / u_resolution.xy;		
		vec2 center = 0.5 - vec2(coord);

		float col = noise(center * 5.0 + 
								${f1}(center.x * 10.0 + u_time * 0.5 + ${f1_1}(center.y * u_time)) + 
								${f2}(center.y * 4.0 + u_time * 0.3 + ${f1_2}(center.x * 2.0 * u_time)) + 
								u_time) * 0.5;

		col += noise(center * 10.0 + 
								cos(center.x * 5.0 + u_time * 0.5) + 
								sin(center.y * 3.0 + u_time) + 
								u_time) * 0.7;

		col -= random(center - col) * 0.3;
		vec3 color = vec3(col, col, col);

		gl_FragColor = vec4(color.x, color.y, color.z, 1.0);
	}
`





// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

// === Tab: ui ===
const function_names = [
  "acos",
  "asin",
  "atan",
  "cos",
  "degrees",
  "radians",
  "sin",
  "tan",
	"floor",
	"ceil",
	"fract",
];


const showState = () => `<p>noise_i:${noise_i}</p> <p>noise_f:${noise_f}</p> <p>f1:${f1}</p> <p>f2:${f2}</p> <p>f1_1:${f1_1}</p> <p>f1_2:${f1_2}</p>`;

const chooseRand = (arr) => arr[Math.floor(Math.random()*arr.length)];

const randomize = () => {
	noise_i=chooseRand(function_names);
	noise_f=chooseRand(function_names);
	f1=chooseRand(function_names);
	f2=chooseRand(function_names);
	f1_1=chooseRand(function_names);
	f1_2=chooseRand(function_names);

	onChangeDropdown();
}

const panel = QuickSettings.create(100, 10, "Func settings")
  .addHTML("NOTE", `<p>initial values are not correct in dropdowns</p> ${showState()}`)
  .addDropDown("noise_i", function_names, (value) => { noise_i = value.value; onChangeDropdown();})
  .addDropDown("noise_f", function_names, (value) => { noise_f = value.value; onChangeDropdown();})
  .addDropDown("f1", function_names, (value) => { f1 = value.value; onChangeDropdown();})
  .addDropDown("f2", function_names, (value) => { f2 = value.value; onChangeDropdown();})
  .addDropDown("f1_1", function_names, (value) => { f1_1 = value.value; onChangeDropdown();})
  .addDropDown("f1_2", function_names, (value) => { f1_2 = value.value; onChangeDropdown();})
	.addButton('randomize', randomize)

const onChangeDropdown = () => {
  // reset shader code
  preload();
  setup();

  // show state of variables
  panel.setValue("NOTE", showState());
};

